-- G4 price-artifact scan (registered in results/PREREG_g4_price_artifacts_2026-10-30.md), written 2026-10-30 BEFORE any candidate was listed. Non-sealed tickers only. Every statement is read-only except V, which creates one view. Run V, then S0 to S5 in order; the SQL editor shows at most 100 rows.
-- V  the view that defines a Part B candidate (non-sealed tickers; one-day adjusted return of 15 percent or more AND a move relative to SPY of at least 6 times the stock own 64-day volatility); ret_raw is the unrounded return; creating it writes no data
CREATE VIEW g4_part_b_candidates AS WITH ns AS (SELECT s.id AS security_id FROM securities s WHERE s.ticker <> $$SPY$$ AND s.ticker NOT IN (SELECT ticker FROM explore_sealed_tickers)), spy AS (SELECT price_date AS d, adjusted_close / LAG(adjusted_close) OVER (ORDER BY price_date) - 1 AS sr FROM market_prices WHERE security_id = (SELECT id FROM securities WHERE ticker = $$SPY$$)), r AS (SELECT p.security_id, p.price_date AS d, p.adjusted_close / LAG(p.adjusted_close) OVER (PARTITION BY p.security_id ORDER BY p.price_date) - 1 AS ret, p.volume::float8 / NULLIF(AVG(p.volume) OVER (PARTITION BY p.security_id ORDER BY p.price_date ROWS BETWEEN 20 PRECEDING AND 1 PRECEDING), 0) AS vol_ratio FROM market_prices p JOIN ns ON ns.security_id = p.security_id), c AS (SELECT r.security_id, r.d, r.ret, r.vol_ratio, r.ret - spy.sr AS rel, spy.sr, ve.v64 FROM r JOIN spy ON spy.d = r.d JOIN vol_estimators ve ON ve.security_id = r.security_id AND ve.d = r.d WHERE r.ret IS NOT NULL AND ABS(r.ret) >= 0.15 AND ve.v64 > 0 AND ABS(r.ret - spy.sr) / ve.v64 >= 6), fk AS (SELECT f.security_id, f.effective_date AS d, f.ratio / LAG(f.ratio) OVER (PARTITION BY f.security_id ORDER BY f.effective_date) AS k FROM price_adjustment_factors f) SELECT s.ticker, c.d, ROUND(c.ret::numeric, 3) AS ret, ROUND((ABS(c.rel) / c.v64)::numeric, 1) AS z, ROUND(c.sr::numeric, 3) AS spy_ret, ROUND(c.vol_ratio::numeric, 1) AS vol_ratio, cpx.d AS cp_date, ROUND(cpx.k::numeric, 3) AS cp_k, (SELECT COUNT(*) FROM sec_8k_filings f WHERE f.security_id = c.security_id AND f.filing_date BETWEEN c.d - 5 AND c.d + 5) AS n_8k_pm5d, LEFT(ev.title, 70) AS nearest_event, c.ret AS ret_raw FROM c JOIN securities s ON s.id = c.security_id LEFT JOIN LATERAL (SELECT fk.d, fk.k FROM fk WHERE fk.security_id = c.security_id AND fk.k IS NOT NULL AND fk.d BETWEEN c.d - 3 AND c.d + 3 ORDER BY ABS(LN(fk.k)) DESC LIMIT 1) cpx ON true LEFT JOIN LATERAL (SELECT e.title FROM events e JOIN event_entity_relationships rr ON rr.event_id = e.id WHERE rr.entity_id = s.entity_id AND e.event_date BETWEEN c.d - 3 AND c.d + 3 ORDER BY ABS(e.event_date::date - c.d) LIMIT 1) ev ON true;
-- S0 PART A (counts, non-sealed tickers): structural checks
WITH ns AS (SELECT s.id AS security_id FROM securities s WHERE s.ticker <> $$SPY$$ AND s.ticker NOT IN (SELECT ticker FROM explore_sealed_tickers)), pp AS (SELECT p.* FROM market_prices p JOIN ns ON ns.security_id = p.security_id) SELECT COUNT(*) AS rows_non_sealed, COUNT(*) FILTER (WHERE NOT EXISTS (SELECT 1 FROM spy_cal sc WHERE sc.d = pp.price_date)) AS not_a_spy_trading_day, COUNT(*) FILTER (WHERE pp.close IS NULL OR pp.adjusted_close IS NULL OR pp.close <= 0 OR pp.adjusted_close <= 0) AS null_or_nonpositive, COUNT(*) FILTER (WHERE pp.high < pp.low) AS high_below_low, COUNT(*) FILTER (WHERE pp.close > pp.high * 1.005 OR pp.close < pp.low * 0.995) AS close_outside_range_0_5pct, COUNT(*) FILTER (WHERE pp.adjusted_close IS DISTINCT FROM pp.close) AS adjusted_differs_from_close, (SELECT COUNT(*) FROM (SELECT security_id, price_date FROM market_prices GROUP BY 1, 2 HAVING COUNT(*) > 1) dd) AS duplicate_stock_days_all_tickers FROM pp;
-- S1 TIER 1a: change points with abs ln k >= 0.10 on a day with a stored move of 10 percent or more (about 18 rows expected)
WITH ns AS (SELECT s.id AS security_id FROM securities s WHERE s.ticker <> $$SPY$$ AND s.ticker NOT IN (SELECT ticker FROM explore_sealed_tickers)), cp AS (SELECT f.security_id, f.effective_date AS d, f.ratio / LAG(f.ratio) OVER (PARTITION BY f.security_id ORDER BY f.effective_date) AS k FROM price_adjustment_factors f JOIN ns ON ns.security_id = f.security_id), cp2 AS (SELECT cp.security_id, cp.d, cp.k, p1.adjusted_close / p0.adjusted_close - 1 AS ret FROM cp LEFT JOIN market_prices p1 ON p1.security_id = cp.security_id AND p1.price_date = cp.d LEFT JOIN LATERAL (SELECT q.adjusted_close FROM market_prices q WHERE q.security_id = cp.security_id AND q.price_date < cp.d ORDER BY q.price_date DESC LIMIT 1) p0 ON true WHERE cp.k IS NOT NULL AND ABS(LN(cp.k)) >= 0.10) SELECT s.ticker, cp2.d, ROUND(cp2.k::numeric, 3) AS k, ROUND(cp2.ret::numeric, 3) AS stored_ret, ROUND(((1 + cp2.ret) / cp2.k - 1)::numeric, 3) AS implied_as_traded_ret_if_traded_is_stored_over_ratio, (SELECT COUNT(*) FROM sec_8k_filings f WHERE f.security_id = cp2.security_id AND f.filing_date BETWEEN cp2.d - 5 AND cp2.d + 5) AS n_8k_pm5d, LEFT((SELECT e.title FROM events e JOIN event_entity_relationships rr ON rr.event_id = e.id WHERE rr.entity_id = s.entity_id AND e.event_date BETWEEN cp2.d - 3 AND cp2.d + 3 ORDER BY ABS(e.event_date::date - cp2.d) LIMIT 1), 70) AS nearest_event FROM cp2 JOIN securities s ON s.id = cp2.security_id WHERE ABS(cp2.ret) >= 0.10 ORDER BY cp2.d, s.ticker;
-- S2 TIER 1b: Part B candidates with a one-day move of 30 percent or more (93 expected)
SELECT ticker, d, ret, z, spy_ret, vol_ratio, cp_date, cp_k, n_8k_pm5d, nearest_event FROM g4_part_b_candidates WHERE ABS(ret_raw) >= 0.30 ORDER BY d, ticker;
-- S3 TIER 1c, first 60: Part B candidates of 15 to 30 percent with NO 8-K within 5 calendar days (about 102 in all)
SELECT ticker, d, ret, z, spy_ret, vol_ratio, cp_date, cp_k, n_8k_pm5d, nearest_event FROM g4_part_b_candidates WHERE ABS(ret_raw) >= 0.15 AND ABS(ret_raw) < 0.30 AND n_8k_pm5d = 0 ORDER BY d, ticker LIMIT 60;
-- S4 TIER 1c, the rest (rows 61 to 160)
SELECT ticker, d, ret, z, spy_ret, vol_ratio, cp_date, cp_k, n_8k_pm5d, nearest_event FROM g4_part_b_candidates WHERE ABS(ret_raw) >= 0.15 AND ABS(ret_raw) < 0.30 AND n_8k_pm5d = 0 ORDER BY d, ticker OFFSET 60 LIMIT 100;
-- S5 TIER 2 SAMPLE: 60 of the Part B candidates of 15 to 30 percent that HAVE an 8-K within 5 calendar days (about 517 in all), in the fixed order of md5(ticker and date)
SELECT ticker, d, ret, z, spy_ret, vol_ratio, cp_date, cp_k, n_8k_pm5d, nearest_event FROM g4_part_b_candidates WHERE ABS(ret_raw) >= 0.15 AND ABS(ret_raw) < 0.30 AND n_8k_pm5d > 0 ORDER BY md5(ticker || d::text) LIMIT 60;
